    """Extend each bottom-row 5 marker column upward from its next seed."""
    out = [row[:] for row in grid]
    h = len(out)
    if not h:
        return out
    w = len(out[0])
    marker_cols = [c for c, value in enumerate(out[-1]) if value == 5]
    for c in marker_cols:
        seeds = [(r, out[r][c]) for r in range(h) if out[r][c] != 0]
        # Each seed projects upward through empty cells, stopping at the
